SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"trial_phase\", \"cancer_type\", \"treatment_regimen\", \"control_regimen\", \"class_of_ici\", \"name_of_ici\", \"type_of_combination\", \"type_of_control\" FROM public.\"clinical_trials\" WHERE \"trial_phase\" = 'Phase 3' AND \"cancer_type\" = 'Melanoma' AND \"class_of_ici\" = 'CTLA4' AND \"name_of_ici\" ILIKE '%CTLA-4%';